from pathlib import Path

p = Path("KONOHA_GAIDEN_ARCS_ZIGRANE_POV_V3/GAMES/KUSAGAKURE_EXAM_EIZAN/EIZAN/ARCS/TOY_KHTO_POMYLIAVSIA_V4-4.txt")
text = p.read_text(encoding="utf-8")

replacements = [
    (
        "Після короткої перерви диктор знову попросив уваги. Третій етап оголосили завершеним. Рішення щодо рангів мали ухвалити після окремого розгляду записів і висновків наставників. Кандидатам їх повідомлять пізніше.",
        "Ми ще трохи сиділи. На поле ніхто більше не виходив."
    ),
    (
        "За тиждень після боїв нас викликали до військової канцелярії. Крім нас, прийшли ще дві місцеві команди. Дев’ятеро генінів зайняли стільці перед столом; наставники лишилися ближче до дверей.",
        "За тиждень після боїв нас викликали до військової канцелярії. Крім нас, прийшли ще дві місцеві команди. У кімнаті було п’ятнадцять людей. Дев’ятеро генінів зайняли стільці перед столом; наставники лишилися ближче до дверей."
    ),
    (
        "На столі перед Сейґо лежав один документ. Він узяв його, коли Шігуре підійшла.",
        "Коли Шігуре підійшла, Сейґо дістав її документ."
    ),
    (
        "— Дай спочатку сісти.\n\nЯ відсунувся з другого боку. Шігуре сіла між нами, тримаючи документ на колінах.\n\nСейґо перейшов до дальших вказівок.",
        "— Дай спочатку сісти.\n\nНаставник неголосно назвав його ім’я.\n\nГоро випрямився. Я відсунувся з другого боку. Шігуре сіла між нами, тримаючи документ на колінах.\n\nСейґо перейшов до дальших вказівок."
    ),
]

for old, new in replacements:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"Expected exactly one match, found {count}: {old[:80]!r}")
    text = text.replace(old, new, 1)

p.write_text(text, encoding="utf-8")
